<script lang="ts">
 import { page } from '$app/state';
 import Seo from '$lib/components/Seo.svelte';
 import { catalogues, catalogueCategories, catalogueFolderUrl } from '$lib/data/catalogues';
 let search = $state('');
 const category = $derived(catalogueCategories.includes(page.url.searchParams.get('category') ?? '') ? page.url.searchParams.get('category')! : 'All');
 const filtered = $derived(catalogues.filter(file => (category === 'All' || file.category === category) && (file.name + ' ' + file.category).toLowerCase().includes(search.trim().toLowerCase())));
</script>
<Seo title="Corporate Gift Catalogues | OfNeeds" description="Browse OfNeeds catalogues for apparel, drinkware, bags, tech, footwear, appliances, stationery and festive gift sets. Preview collections or request a copy." crumb="Catalogues" />
<section class="catalogue-intro"><div class="container"><p class="eyebrow">Your next idea starts here</p><h1>The OfNeeds<br /><span>Catalogue Library.</span></h1><p>Explore the details. Discover the possibilities. Find a collection for your team, your occasion and your brand.</p><div class="catalogue-intro-actions"><a class="text-link" href="/contact#quote">Need a curated selection? Talk to our team →</a><a class="text-link" href={catalogueFolderUrl} target="_blank" rel="noopener noreferrer">View shared Drive folder ↗</a></div></div></section>
<section class="section catalogue-library"><div class="container">
 <div class="catalogue-toolbar"><h2>Find your collection</h2><label>Search catalogues<input type="search" bind:value={search} placeholder="Try bottles, notebooks or pens" /></label></div>
 <nav class="catalogue-filters" aria-label="Catalogue categories">{#each catalogueCategories as item (item)}<a href={item === 'All' ? '/catalogues' : '/catalogues?category=' + encodeURIComponent(item)} class:selected={category === item} aria-current={category === item ? 'page' : undefined}>{item}</a>{/each}</nav>
 <p class="catalogue-count" aria-live="polite">{filtered.length} {filtered.length === 1 ? 'catalogue' : 'catalogues'}</p>
 <div class="catalogue-grid">
  {#each filtered as file (file.id)}<article class="catalogue-card">
   <a class="catalogue-cover" href={file.preview} target="_blank" rel="noopener noreferrer" aria-label={'Open ' + file.name + ' in Google Drive (opens in a new tab)'}>{#if file.hasCover}<img src={file.image} alt={file.alt} width={file.width} height={file.height} loading="lazy" decoding="async" />{:else}<div class="catalogue-placeholder"><svg viewBox="0 0 72 88" width="72" height="88" fill="none" aria-hidden="true"><path d="M14 3h29l15 16v66H14z" stroke="currentColor" stroke-width="2"/><path d="M43 3v18h15M24 40h24M24 51h24M24 62h16" stroke="currentColor" stroke-width="2"/></svg><span>{file.format} catalogue</span></div>{/if}</a>
   <div class="catalogue-info">{#if !file.hasCover}<p class="catalogue-meta">Cover preview unavailable</p>{/if}<p class="catalogue-meta">{file.category} · {file.format}{#if file.size} · {file.size}{/if}</p><h3>{file.name.replace(/\.(pdf|pptx)$/i, '')}</h3>{#if !file.available}<p class="catalogue-status">This Drive file is currently empty. Request a catalogue copy from our team.</p>{/if}<div class="catalogue-actions"><a href={file.preview} target="_blank" rel="noopener noreferrer" aria-label={'Open ' + file.name + ' in Google Drive (opens in a new tab)'}>{file.available ? 'Preview ↗' : 'Open in Drive ↗'}</a>{#if file.available}<a class="download-link" href={file.download} target="_blank" rel="noopener noreferrer" aria-label={'Download ' + file.name + ' from Google Drive'}>Download ↓</a>{:else}<a class="download-link" href="/contact#quote">Request catalogue →</a>{/if}</div></div>
  </article>{:else}<div class="catalogue-empty"><h3>No matching catalogues</h3><p>Try a different search or choose another category.</p><button type="button" class="button" onclick={() => search = ''}>Clear search</button></div>{/each}
 </div>
 <p class="catalogue-note">Preview and download links open Google Drive. Collections include the editions shown in their file names. Share the product name or code with our team to confirm availability, branding and current pricing.</p>
 <div class="catalogue-cta"><div><h2>Found something you like?</h2><p>Bring us your shortlist. We’ll bring your brand to life.</p></div><a class="button" href="/contact#quote">Request a Quote →</a></div>
</div></section>
