 @media(max-width:600px){.catalogue-intro{padding:48px 0}.catalogue-toolbar,.catalogue-cta{flex-direction:column;align-items:flex-start}.catalogue-grid{grid-template-columns:1fr}.catalogue-cover img{height:260px}.catalogue-info h3{min-height:0}.catalogue-cta{padding:24px}.catalogue-filters a{padding:9px 13px}}
